// Modèle Word et images de l'en-tête de l'étude, pour le générateur d'appel de fonds
// (voir « Générateur d'appel de fonds » dans CLAUDE.md).
//
// Pourquoi un fichier à part, chargé À LA DEMANDE : ces deux données ne servent qu'à cet
// outil, pour un usage ponctuel, et pèsent ensemble ~350 Ko. Les charger dans index.html
// ralentirait CHAQUE ouverture de CLAIRE pour rien — chargerModeleAppelFonds() (script.js)
// injecte ce script au premier passage dans l'onglet, puis le garde en mémoire.
//
// À NE PAS OUBLIER : ce fichier doit être déclaré dans ASSETS_STATIQUES (server/src/app.js)
// ET dans les assets embarqués du .exe (server/scripts/build-windows-exe.mjs). Sans ça le
// chargement fait un 404 et la génération du .docx échoue — le même piège que pour
// questionnaire-satisfaction-pdf.js.
//
// Le .docx est le vrai modèle à en-tête de l'étude, rempli par docxtemplater. Les images
// sont celles de cet en-tête, redimensionnées au double de leur taille d'affichage dans
// l'aperçu (l'icône Instagram d'origine pesait 98 Ko pour un rendu de 13 px de côté).
window.APPEL_FONDS_MODELE = {
  docxB64: "",
  assets: {
    logoNotaires: "data:image/png;base64,",
    logoOffice: "data:image/png;base64,",
    iconVisio: "data:image/png;base64,",
    iconFacebook: "data:image/png;base64,",
    tampon: "data:image/png;base64,",
    signature: "data:image/png;base64,",
    iconInstagram: "data:image/png;base64,",
  }
};
